#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <limits.h>

static int is_decimal_number(const char *s)
{
    if (*s == '\0')
        return 0;
    while (*s) {
        if (*s < '0' || *s > '9')
            return 0;
        ++s;
    }
    return 1;
}

static int parse_long(const char *s, long *out)
{
    char *endptr;
    long v;

    if (!is_decimal_number(s))
        return 0;
    errno = 0;
    v = strtol(s, &endptr, 10);
    if (errno != 0 || *endptr != '\0')
        return 0;
    *out = v;
    return 1;
}

int main(int argc, char **argv)
{
    long mode, limit;
    double result = 0.0;

    if (argc < 3) {
        puts("NO_INPUT");
        return 0;
    }

    if (!parse_long(argv[1], &mode) || !parse_long(argv[2], &limit)) {
        puts("BAD_INPUT");
        return 0;
    }

    if (limit < 0) {
        puts("BAD_INPUT");
        return 0;
    }
    if (limit > 100000) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    switch (mode) {
        case 1:
            for (long i = 1; i <= limit; ++i) {
                result += 1.0 / ((double)i * (double)i);
            }
            break;
        case 2:
            for (long i = 1; i <= limit; ++i) {
                double term = 1.0 / ((double)i * (double)i);
                if ((i & 1) == 0)
                    term = -term;
                result += term;
            }
            break;
        case 3:
        {
            double term = 1.0;
            result = 1.0;
            for (long i = 1; i <= limit; ++i) {
                term /= (double)i;
                result += term;
            }
        }
            break;
        default:
            puts("BAD_MODE");
            return 0;
    }

    printf("%.6f\n", result);
    return 0;
}
